WITH t AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, JENIS_PUPUK j, SUM(IFF(STATUS LIKE 'TM%' AND BULAN<'2026-10-01',TARGET_KG,0)) tm, SUM(IFF(COALESCE(STATUS,'') LIKE 'TM%' OR BULAN>='2026-10-01',0,TARGET_KG)) nontm, SUM(IFF(STATUS LIKE 'TM%',TARGET_KG,0)) fy FROM PRD_DB_INTEGRATION.INT_RAWAT.INT_PUPUK_TARGET WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2027-01-01' GROUP BY 1,2,3), h AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, NAMA_PUPUK j, SUM(IFF(STATUS_MATURITY='TM',KG_AKTUAL,0)) tm, SUM(IFF(COALESCE(STATUS_MATURITY,'')='TM',0,KG_AKTUAL)) nontm FROM PRD_DB_INTEGRATION.INT_RAWAT.INT_PUPUK_HARIAN WHERE KODE_BA IN ('2121','2124','2131','2122') AND TANGGAL_PUPUK>='2026-01-01' AND TANGGAL_PUPUK<'2026-10-01' GROUP BY 1,2,3) SELECT COALESCE(t.ba,h.ba) ba, COALESCE(t.afd,h.afd) afd, COALESCE(t.j,h.j) j, ROUND(COALESCE(t.tm,0)) tgt_tm, ROUND(COALESCE(h.tm,0)) act_tm, ROUND(COALESCE(t.nontm,0)) tgt_nontm, ROUND(COALESCE(h.nontm,0)) act_nontm, ROUND(COALESCE(t.fy,0)) tgt_fy FROM t FULL OUTER JOIN h ON t.ba=h.ba AND t.afd=h.afd AND t.j=h.j WHERE COALESCE(t.fy,0)<>0 OR COALESCE(t.nontm,0)<>0 OR COALESCE(h.tm,0)<>0 OR COALESCE(h.nontm,0)<>0 ORDER BY 1,2,3